/* BeatForge Sample Engine v5. Recorded one-shot WAV playback (CC0 licensed).
 * Drum patterns are generated by BeatForge/GMD; timbre comes from WAV files.
 * MIDI bass pitches use adjustable reference MIDI key, default 36/C2.
 * No synthesizer fallback for kick, snare, hats or 808 bass.
 */
(() => {
  'use strict';
  const ROOT = './samples/';
  const KITS = {
    hard: {name:'Hard Trap',description:'Heavy kick · crisp hats · distorted 808', lanes:{
      kick:['hard/kick.wav','hard/kick-alt.wav'],snare:['hard/snare.wav','hard/snare-alt.wav'],
      hat:['hard/hat.wav','hard/hat-alt.wav'],openhat:['hard/openhat.wav'],
      bass:['hard/808-dist.wav','hard/808-sub.wav'],clap:['hard/clap.wav']
    }},
    bounce:{name:'Bounce',description:'Punchy drums · clean 808',lanes:{
      kick:['bounce/kick.wav'],snare:['bounce/snare.wav'],hat:['bounce/hat.wav'],
      openhat:['bounce/openhat.wav'],bass:['bounce/808.wav']
    }},
    vintage:{name:'Soulful Vintage',description:'Lo-fi hats · warm 808',lanes:{
      kick:['vintage/kick.wav'],snare:['vintage/snare.wav'],hat:['vintage/hat.wav'],
      openhat:['vintage/openhat.wav'],bass:['vintage/808.wav']
    }}
  };
  const tracks = ['kick','snare','hat','openhat','bass'];
  const prefsKey='beatforge_sample_config_v1';
  const bufferCache=new Map(), requests=new Map(), fail=new Map();
  let decodeCtx=null, auditionCtx=null, panel=null;
  let config={kit:'hard',root:36,clap:true,variants:{}};
  try{const saved=JSON.parse(localStorage.getItem(prefsKey)||'null');if(saved&&typeof saved==='object'){
    config.kit=KITS[saved.kit]?saved.kit:config.kit;
    config.root=Number.isInteger(saved.root)&&saved.root>=24&&saved.root<=72?saved.root:36;
    config.clap=saved.clap!==false;config.variants=saved.variants&&typeof saved.variants==='object'?saved.variants:{};
  }}catch(_){/* Privacy mode may disable storage */}
  const save=()=>{try{localStorage.setItem(prefsKey,JSON.stringify(config))}catch(_){}};
  function fileFor(kit,lane){const options=KITS[kit]?.lanes[lane];if(!options)return null;
    const choice=config.variants[kit+':'+lane];return options[Math.min(options.length-1,Math.max(0,Number.isInteger(choice)?choice:0))];
  }
  function filesFor(kit){return [...new Set(Object.values(KITS[kit].lanes).flat())]}
  function readyForSong(song){return requiredFiles(song).every(name=>bufferCache.has(name));}
  function requiredFiles(song){const kit=config.kit;const lanes=new Set((song?.events||[]).map(x=>x.lane));const names=[];
    for(const lane of tracks)if(lanes.has(lane)){let f=fileFor(kit,lane);if(f)names.push(f)}
    if(config.clap&&lanes.has('snare')&&fileFor(kit,'clap'))names.push(fileFor(kit,'clap'));
    return [...new Set(names)];
  }
  function getDecoder(){if(!decodeCtx){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('AudioContext nicht verfügbar');decodeCtx=new AC()};return decodeCtx}
  async function readOne(path){if(bufferCache.has(path))return bufferCache.get(path);if(requests.has(path))return requests.get(path);
    const work=(async()=>{
      // Prefer licensed prerecorded WAVs embedded in a verified offline sample bank.
      const embedded=window.BeatforgeSampleBank?.[path];
      let binary;
      if(typeof embedded==='string'&&embedded.length>100){
        const decoded=atob(embedded),bytes=new Uint8Array(decoded.length);
        for(let i=0;i<decoded.length;i++)bytes[i]=decoded.charCodeAt(i);
        binary=bytes.buffer;
      }else{
        const response=await fetch(ROOT+path,{cache:'force-cache'});
        if(!response.ok)throw Error(`HTTP ${response.status}: ${path}`);
        binary=await response.arrayBuffer();
      }
      if(binary.byteLength<80||binary.byteLength>15000000)throw Error('Ungültiges WAV: '+path);
      const buffer=await getDecoder().decodeAudioData(binary.slice(0));
      if(!buffer.duration||!Number.isFinite(buffer.duration))throw Error('Beschädigtes Audio: '+path);
      bufferCache.set(path,buffer);fail.delete(path);return buffer;
    })();requests.set(path,work);try{return await work}catch(err){fail.set(path,err.message||String(err));throw err}finally{requests.delete(path);refresh()}
  }
  async function preloadKit(kit=config.kit,full=false){const names=full?filesFor(kit):requiredFiles(window.Beatforge?.getSong?.());
    const done=await Promise.allSettled(names.map(readOne));refresh();const rejected=done.filter(x=>x.status==='rejected');
    if(rejected.length)throw Error(`${rejected.length} Samples konnten nicht geladen werden. Prüfe die Verbindung und tippe auf „Erneut laden“.`);
    return true;
  }
  async function ensureForSong(song){const files=requiredFiles(song);const done=await Promise.allSettled(files.map(readOne));refresh();if(done.some(x=>x.status==='rejected'))throw Error('Samples fehlen: '+[...new Set(files.filter(x=>!bufferCache.has(x)))].join(', '));return true}
  function oneShot(ctx,buffer,at,vol,output,opts={}){
    if(!buffer||!ctx||!output)return false;
    const time=Math.max(at,ctx.currentTime+.001),src=ctx.createBufferSource(),gain=ctx.createGain();
    src.buffer=buffer;
    const rate=Math.max(.18,Math.min(5,opts.rate||1));src.playbackRate.setValueAtTime(rate,time);
    const natural=buffer.duration/rate;
    const gate=opts.gate>0?Math.min(natural,opts.gate):natural;
    const end=Math.max(.016,gate);
    gain.gain.setValueAtTime(.00001,time);
    gain.gain.linearRampToValueAtTime(Math.max(.0001,Math.min(1.5,vol)),time+.003);
    const release=Math.min(.065,end*.38);
    gain.gain.setValueAtTime(Math.max(.0001,Math.min(1.5,vol)),time+Math.max(.004,end-release));
    gain.gain.linearRampToValueAtTime(.00001,time+end);
    src.connect(gain);gain.connect(output);
    src.start(time);src.stop(time+end+.015);
    return true;
  }
  function renderEvent(ctx,s,event,t,d,v,output){
    const lane=event.lane;
    if(!tracks.includes(lane))return false;
    const kit=config.kit;
    const path=fileFor(kit,lane);
    const buf=bufferCache.get(path);
    if(!buf)return true; // Important: never silently synthesize instead of using samples.
    const volume=lane==='bass'?Math.min(1.2,v*.72):lane==='kick'?v*.78:lane==='snare'?v*.73:lane==='hat'?v*.52:v*.58;
    const pitch=Number.isFinite(event.pitch)?event.pitch:36;
    const rate=lane==='bass'?Math.pow(2,(pitch-config.root)/12):1;
    oneShot(ctx,buf,t,volume,output,{rate,gate:lane==='bass'?Math.max(.08,d):0});
    if(lane==='snare'&&config.clap){const clap=fileFor(kit,'clap');if(clap&&bufferCache.has(clap))oneShot(ctx,bufferCache.get(clap),t,v*.20,output)}
    return true;
  }
  function noteName(m){return ['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'][m%12]+(Math.floor(m/12)-1)}
  function preview(lane){const f=fileFor(config.kit,lane);const buf=bufferCache.get(f);
    if(!buf){preloadKit(config.kit,true).catch(showError);showError('Sample wird geladen, danach erneut tippen.');return}
    try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('Web Audio nicht unterstützt');
      if(!auditionCtx||auditionCtx.state==='closed')auditionCtx=new AC();
      oneShot(auditionCtx,buf,auditionCtx.currentTime+.02,.7,auditionCtx.destination);
      auditionCtx.resume().catch(showError);
    }catch(e){showError(e)}
  }
  function showError(err){const info=panel?.querySelector('#bfSampleStatus');if(info){info.textContent=String(err?.message||err);info.dataset.error='1'}}
  function refresh(){if(!panel)return;
    const status=panel.querySelector('#bfSampleStatus');if(!status)return;
    const paths=filesFor(config.kit),ready=paths.filter(x=>bufferCache.has(x)).length,pending=paths.filter(x=>requests.has(x)).length,broken=paths.filter(x=>fail.has(x)).length;
    status.textContent=ready===paths.length?`Alle ${ready} echten WAV-Samples einsatzbereit · Offline nutzbar`:`${ready}/${paths.length} WAV-Samples geladen${pending?' · '+pending+' laufen':''}${broken?' · '+broken+' Fehler':''}`;
    status.dataset.error=broken?'1':'0';
    for(const btn of panel.querySelectorAll('[data-preview]'))btn.disabled=!bufferCache.has(fileFor(config.kit,btn.dataset.preview));
  }
  function setup(){const target=document.getElementById('studioTab');if(!target||document.getElementById('bfSampleRack'))return;
    panel=document.createElement('section');panel.className='panel bf-sample-panel';panel.id='bfSampleRack';
    panel.innerHTML=`<div class="bf-sample-head"><div><span class="bf-sample-eyebrow">SAMPLE-BASED SOUND ENGINE</span><h2>Real Drum Kits · WAV</h2><p>Keine synthetischen Drums: WAV-One-Shots aus echten Sample-Packs. Groove-KI steuert nur die Schläge.</p></div><span class="bf-sample-pill">CC0</span></div>
    <div class="bf-sample-settings"><label>Sample-Kit<select id="bfKit"></select></label><label>808 Grundnote<select id="bfRoot"></select></label></div>
    <p id="bfSampleStatus" role="status" aria-live="polite">Samples werden geladen …</p>
    <div id="bfSamplePads" class="bf-sample-pads"></div>
    <div class="bf-sample-bottom"><label class="bf-clap"><input id="bfClap" type="checkbox" /> Clap mit Snare layern</label><button type="button" id="bfRetry" class="btn">Sounds erneut laden</button></div>
    <small class="bf-sample-credit">Quelle: Boochi44 Free Drum Samples (CC0 1.0), teilweise aus aufgenommenen TR-808-Samples. 808-Grundnote bei Bedarf anpassen. <a href="https://github.com/Boochi44/free-drum-samples" target="_blank" rel="noopener noreferrer">Lizenz &amp; Quelle</a></small>`;
    const generator=document.getElementById('generatorPanel');generator?.after(panel);
    const kitSelect=panel.querySelector('#bfKit'),root=panel.querySelector('#bfRoot');
    Object.entries(KITS).forEach(([key,v])=>kitSelect.add(new Option(v.name,key)));
    kitSelect.value=config.kit;
    for(let n=24;n<=72;n++)root.add(new Option(noteName(n),String(n)));root.value=String(config.root);
    panel.querySelector('#bfClap').checked=config.clap;
    kitSelect.addEventListener('change',()=>{config.kit=kitSelect.value;save();renderPads();preloadKit(config.kit,true).catch(showError)});
    root.addEventListener('change',()=>{config.root=Number(root.value);save()});
    panel.querySelector('#bfClap').addEventListener('change',event=>{config.clap=event.target.checked;save()});
    panel.querySelector('#bfRetry').addEventListener('click',()=>preloadKit(config.kit,true).catch(showError));
    function renderPads(){const wrap=panel.querySelector('#bfSamplePads');wrap.replaceChildren();
      for(const lane of [...tracks,'clap'].filter(name=>KITS[config.kit].lanes[name])){
        const options=KITS[config.kit].lanes[lane],title={kick:'Kick',snare:'Snare',hat:'Closed Hi-Hat',openhat:'Open Hi-Hat',bass:'808 Bass',clap:'Clap'}[lane];
        const cell=document.createElement('div');cell.className='bf-sample-pad';
        const bt=document.createElement('button');bt.type='button';bt.dataset.preview=lane;bt.className='bf-pad-audition';bt.textContent='▶';bt.setAttribute('aria-label',`${title} anhören`);bt.onclick=()=>preview(lane);
        const field=document.createElement('div');field.className='bf-pad-info';const cap=document.createElement('strong');cap.textContent=title;field.append(cap);
        if(options.length>1){const sel=document.createElement('select');sel.setAttribute('aria-label',`${title} Variante`);
          options.forEach((path,i)=>sel.add(new Option('Sample '+(i+1),i)));sel.value=String(config.variants[config.kit+':'+lane]||0);
          sel.onchange=()=>{config.variants[config.kit+':'+lane]=Number(sel.value);save();preloadKit(config.kit,true).catch(showError);refresh()};field.append(sel)}
        else{const hint=document.createElement('small');hint.textContent='WAV One-Shot';field.append(hint)}
        cell.append(bt,field);wrap.append(cell);
      }
      refresh();
    }
    renderPads();preloadKit(config.kit,true).catch(showError);
    const desc=target.querySelector('.pocket-export-tip');if(desc)desc.textContent='WAV-Export nutzt echte Drum-/808-Samples aus dem ausgewählten Kit; Melodie/Akkorde sind weiterhin Synthesizer.';
  }
  const api={renderEvent,readyForSong,ensureForSong,preloadKit,refresh,getStatus:()=>({kit:config.kit,files:filesFor(config.kit).length,ready:filesFor(config.kit).filter(x=>bufferCache.has(x)).length,errors:[...fail]}),getConfig:()=>JSON.parse(JSON.stringify(config)),setKit:async kit=>{if(!KITS[kit])throw Error('Kit unbekannt');config.kit=kit;save();const sel=panel?.querySelector('#bfKit');if(sel)sel.value=kit;await preloadKit(kit,true);setup();return true;}};
  window.BeatforgeSampleEngine=api;
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',setup,{once:true});else setup();
})();